#!/usr/bin/env bash
# Secret scan of the whole history and of the working tree. Uses a local gitleaks if installed,
# else the pinned image (same pin as prj_django_tenant_lab).
#
# The working-tree scan covers what git could commit: tracked files plus untracked files that
# are not ignored. Gitignored local lab material (secrets/, deploy/certs/: generated by
# `make secrets certs`, never committed) is left out on purpose; the history scan would catch it
# if it were ever committed.
set -euo pipefail
cd "$(git rev-parse --show-toplevel)"
IMAGE=zricethezav/gitleaks:v8.30.1@sha256:c00b6bd0aeb3071cbcb79009cb16a60dd9e0a7c60e2be9ab65d25e6bc8abbb7f
snapshot=$(mktemp -d "${TMPDIR:-/tmp}/gitleaks-tree.XXXXXX")
trap 'rm -rf -- "${snapshot:?}"' EXIT
git ls-files -z --cached --others --exclude-standard \
  | while IFS= read -r -d '' f; do [ -f "$f" ] && printf '%s\0' "$f"; done \
  | tar --null -T - -cf - | tar -xf - -C "$snapshot"
if command -v gitleaks >/dev/null; then
  gitleaks git --redact --no-banner .
  gitleaks dir --redact --no-banner "$snapshot"
else
  docker run --rm -v "$PWD:/repo:ro" "$IMAGE" git --redact --no-banner /repo
  docker run --rm -v "$snapshot:/tree:ro" "$IMAGE" dir --redact --no-banner /tree
fi
